/**
 * Claude (Opus 5.5) | 2026-10-08 | Glosario bilingüe de AI-103: 71 términos, de 4 a 6 por cada una de las 14 subhabilidades oficiales.
 * Reemplaza la pestaña Términos (antes 14 entradas armadas a partir de una pregunta de ejemplo). Se carga después de study_azure_ai103_resources.js.
 */
(function () {
  const TERMS = [{"subskill":"1.1","name_en":"Microsoft Foundry resource and project","name_es":"Recurso y proyecto de Microsoft Foundry","definition_en":"The Foundry resource (kind AIServices) is the top-level Azure resource that holds model deployments, Foundry Tools and shared networking and security settings. A Foundry project is a child of that resource that groups agents, evaluations, files and connections for one team or app, and exposes a single project endpoint (https://{resource}.services.ai.azure.com/api/projects/{project}).","definition_es":"El recurso de Foundry (kind AIServices) es el recurso de Azure de nivel superior que contiene las implementaciones de modelos, las Foundry Tools y la configuración compartida de red y seguridad. Un proyecto de Foundry es un hijo de ese recurso que agrupa agentes, evaluaciones, archivos y conexiones de un equipo o una app, y expone un único endpoint de proyecto (https://{resource}.services.ai.azure.com/api/projects/{project}).","exam_tip_en":"Agents, Foundry Agent Service and the azure-ai-projects SDK work against the project endpoint, not the resource endpoint. Hub-based projects are the older model; new scenarios use Foundry projects.","exam_tip_es":"Los agentes, Foundry Agent Service y el SDK azure-ai-projects trabajan contra el endpoint del proyecto, no contra el del recurso. Los proyectos basados en hub son el modelo anterior; los escenarios nuevos usan proyectos de Foundry.","relevance":"alta"},{"subskill":"1.1","name_en":"Multi-service resource (single endpoint and key)","name_es":"Recurso multiservicio (un endpoint y una clave)","definition_en":"A Foundry resource (or the older CognitiveServices kind) exposes several Foundry Tools, such as Language, Speech, Vision and Translator, behind one endpoint and one pair of keys. A single-service resource (for example kind TextAnalytics or SpeechServices) exposes only one service.","definition_es":"Un recurso de Foundry (o el tipo anterior CognitiveServices) expone varias Foundry Tools, como Language, Speech, Vision y Translator, detrás de un endpoint y un par de claves. Un recurso de un solo servicio (por ejemplo kind TextAnalytics o SpeechServices) expone solo un servicio.","exam_tip_en":"When the question says one endpoint and one credential for several services, pick the multi-service resource. Pick a single-service resource only when the question needs separate billing or a feature tied to that resource type.","exam_tip_es":"Si la pregunta pide un endpoint y una credencial para varios servicios, elige el recurso multiservicio. Elige un recurso de un solo servicio solo si piden facturación separada o una función propia de ese tipo de recurso.","relevance":"media"},{"subskill":"1.1","name_en":"Model catalog, model cards and leaderboards","name_es":"Catálogo de modelos, fichas de modelo y leaderboards","definition_en":"The Foundry model catalog lists models sold directly by Azure (Azure OpenAI and others) and partner or community models. Model cards describe intended use, limits and supported deployment types, and leaderboards compare models by quality, safety, cost and throughput benchmarks.","definition_es":"El catálogo de modelos de Foundry incluye modelos vendidos directamente por Azure (Azure OpenAI y otros) y modelos de socios o de la comunidad. Las fichas de modelo describen el uso previsto, los límites y los tipos de implementación admitidos, y los leaderboards comparan modelos por benchmarks de calidad, seguridad, costo y rendimiento.","exam_tip_en":"Use leaderboards to compare candidate models before deploying. Private endpoints, vector indexes and tool catalogs never answer a \"compare quality, cost and throughput\" question.","exam_tip_es":"Usa los leaderboards para comparar modelos antes de implementarlos. Un private endpoint, un índice vectorial o un catálogo de herramientas nunca responde a \"comparar calidad, costo y rendimiento\".","relevance":"media"},{"subskill":"1.1","name_en":"Choosing a model family by task","name_es":"Elegir la familia de modelos según la tarea","definition_en":"Match the task verb to the model: an LLM or reasoning model generates and reasons, an embedding model turns text into vectors, a small language model (SLM) handles light low-latency tasks, Whisper or Azure Speech transcribes audio, and gpt-image or Sora create images or video. Prebuilt Foundry Tools (Language, Vision, Document Intelligence) solve narrow tasks without prompting.","definition_es":"Relaciona el verbo de la tarea con el modelo: un LLM o un modelo de razonamiento genera y razona, un modelo de embeddings convierte texto en vectores, un modelo de lenguaje pequeño (SLM) cubre tareas ligeras de baja latencia, Whisper o Azure Speech transcriben audio, y gpt-image o Sora crean imágenes o video. Las Foundry Tools precompiladas (Language, Vision, Document Intelligence) resuelven tareas concretas sin prompts.","exam_tip_en":"Vectors always come from an embedding model, never from an LLM. An SLM is wrong when the question says deep multi-step reasoning over long context.","exam_tip_es":"Los vectores siempre salen de un modelo de embeddings, nunca de un LLM. Un SLM es incorrecto cuando la pregunta habla de razonamiento profundo de varios pasos sobre contexto largo.","relevance":"alta"},{"subskill":"1.1","name_en":"Model router","name_es":"Model router (enrutador de modelos)","definition_en":"Model router is a deployable Foundry model that inspects each prompt and sends it to the most suitable underlying chat model, balancing quality, cost and latency. You deploy it once and call it like any other chat deployment.","definition_es":"Model router es un modelo de Foundry que se implementa como cualquier otro y que analiza cada prompt para enviarlo al modelo de chat subyacente más adecuado, equilibrando calidad, costo y latencia. Se implementa una vez y se llama como cualquier implementación de chat.","exam_tip_en":"Pick it when the question asks to cut cost on simple prompts without losing quality on hard ones and with minimal code. Routing all traffic to a smaller model is the trap.","exam_tip_es":"Elígelo cuando piden bajar el costo de los prompts simples sin perder calidad en los difíciles y con poco código. Enviar todo el tráfico a un modelo más pequeño es la trampa.","relevance":"media"},{"subskill":"1.2","name_en":"Global Standard deployment","name_es":"Implementación Global Standard","definition_en":"A pay-per-token deployment type whose inference can be processed in any Azure region worldwide. It has the highest default quota and is the recommended starting point when there are no data residency limits.","definition_es":"Tipo de implementación de pago por token cuya inferencia se puede procesar en cualquier región de Azure del mundo. Tiene la cuota predeterminada más alta y es el punto de partida recomendado cuando no hay restricciones de residencia de datos.","exam_tip_en":"Wrong whenever the question requires data to stay in a geography or zone: then use Standard (regional) or Data Zone Standard.","exam_tip_es":"Es incorrecta cuando la pregunta exige que los datos queden en una geografía o zona: en ese caso usa Standard (regional) o Data Zone Standard.","relevance":"alta"},{"subskill":"1.2","name_en":"Standard and Data Zone Standard deployments","name_es":"Implementaciones Standard y Data Zone Standard","definition_en":"Standard (regional) processes inference inside the Azure geography of the resource, pay per token. Data Zone Standard processes inference inside a Microsoft data zone (US or EU) with higher quota than regional Standard.","definition_es":"Standard (regional) procesa la inferencia dentro de la geografía de Azure del recurso, con pago por token. Data Zone Standard procesa la inferencia dentro de una zona de datos de Microsoft (EE. UU. o UE) con más cuota que Standard regional.","exam_tip_en":"Low or variable traffic plus strict residency points to Standard. Residency at EU or US level with more quota points to Data Zone Standard.","exam_tip_es":"Tráfico bajo o variable con residencia estricta apunta a Standard. Residencia a nivel UE o EE. UU. con más cuota apunta a Data Zone Standard.","relevance":"alta"},{"subskill":"1.2","name_en":"Provisioned throughput (PTU)","name_es":"Rendimiento aprovisionado (PTU)","definition_en":"Provisioned deployments (Global, Data Zone or Regional) reserve model processing capacity measured in provisioned throughput units. You pay an hourly rate or a reservation whether or not you use it, and get predictable latency.","definition_es":"Las implementaciones aprovisionadas (Global, Data Zone o Regional) reservan capacidad de procesamiento medida en unidades de rendimiento aprovisionado (PTU). Se paga una tarifa por hora o una reserva se use o no, y se obtiene una latencia predecible.","exam_tip_en":"Choose PTU for high, steady volume with latency SLAs. It is the trap for variable, low-volume or cost-sensitive traffic. HTTP 429 on PTU means the reserved capacity is full.","exam_tip_es":"Elige PTU para volumen alto y constante con SLA de latencia. Es la trampa cuando el tráfico es variable, bajo o sensible al costo. Un HTTP 429 en PTU significa que la capacidad reservada está llena.","relevance":"alta"},{"subskill":"1.2","name_en":"Global Batch and Data Zone Batch","name_es":"Global Batch y Data Zone Batch","definition_en":"Batch deployments process large asynchronous jobs submitted as JSONL files, with a 24-hour target turnaround and about 50% lower cost than Global Standard. They use a separate enqueued-token quota and do not serve real-time requests.","definition_es":"Las implementaciones Batch procesan grandes trabajos asíncronos enviados como archivos JSONL, con un plazo objetivo de 24 horas y un costo cerca de 50% menor que Global Standard. Usan una cuota propia de tokens en cola y no atienden solicitudes en tiempo real.","exam_tip_en":"Keywords: nightly, offline, large volume, cheapest, no real-time need. Never the answer when users wait for a response.","exam_tip_es":"Palabras clave: nocturno, sin conexión, gran volumen, lo más barato, sin necesidad de tiempo real. Nunca es la respuesta si un usuario espera la respuesta.","relevance":"media"},{"subskill":"1.2","name_en":"Version upgrade policy","name_es":"Política de actualización de versión","definition_en":"Each deployment sets what happens when a model gets a new default version or the current version retires: upgrade once the current version expires, upgrade as soon as a new default version is available, or opt out of automatic upgrades. Opting out means the deployment stops working when the version retires.","definition_es":"Cada implementación define qué pasa cuando el modelo tiene una nueva versión predeterminada o la versión actual se retira: actualizar cuando la versión actual expire, actualizar en cuanto haya una nueva versión predeterminada, o no actualizar automáticamente. Si se desactiva la actualización, la implementación deja de funcionar cuando la versión se retira.","exam_tip_en":"For consistent behavior with continuity, choose \"once the current version expires\". Opt-out looks safe but breaks the deployment at retirement.","exam_tip_es":"Para un comportamiento estable sin interrupciones, elige \"cuando la versión actual expire\". No actualizar parece seguro, pero rompe la implementación al retirarse la versión.","relevance":"alta"},{"subskill":"1.2","name_en":"Project connections","name_es":"Conexiones del proyecto","definition_en":"A connection stores the target and authentication of an external resource (Azure AI Search, Storage, Key Vault, an API key) once in the Foundry project or resource. Agents, tools and apps reference the connection instead of holding their own credentials.","definition_es":"Una conexión guarda una sola vez, en el proyecto o recurso de Foundry, el destino y la autenticación de un recurso externo (Azure AI Search, Storage, Key Vault, una clave de API). Los agentes, herramientas y apps hacen referencia a la conexión en lugar de tener sus propias credenciales.","exam_tip_en":"Answer when several agents or apps must share one configuration with centralized credentials and minimal admin effort. RBAC or a private endpoint alone does not centralize configuration.","exam_tip_es":"Es la respuesta cuando varios agentes o apps deben compartir una configuración con credenciales centralizadas y poco esfuerzo administrativo. RBAC o un private endpoint por sí solos no centralizan la configuración.","relevance":"media"},{"subskill":"1.3","name_en":"Keyless authentication with Microsoft Entra ID","name_es":"Autenticación sin claves con Microsoft Entra ID","definition_en":"Apps authenticate to Foundry with DefaultAzureCredential or a managed identity and receive a token, so no API key is stored. Access is granted with Azure RBAC roles such as Azure AI User or Cognitive Services OpenAI User at the narrowest scope.","definition_es":"Las apps se autentican en Foundry con DefaultAzureCredential o una identidad administrada y reciben un token, así que no se guarda ninguna clave de API. El acceso se concede con roles de Azure RBAC, como Azure AI User o Cognitive Services OpenAI User, en el ámbito más reducido.","exam_tip_en":"Words like keyless, no secrets or least privilege mean managed identity plus a specific data-plane role. AzureKeyCredential and client secrets are the traps; Contributor is too broad for inference.","exam_tip_es":"Palabras como sin claves, sin secretos o mínimo privilegio significan identidad administrada más un rol específico del plano de datos. AzureKeyCredential y los client secrets son las trampas; Contributor es demasiado amplio para inferencia.","relevance":"alta"},{"subskill":"1.3","name_en":"Key rotation without downtime","name_es":"Rotación de claves sin interrupción","definition_en":"Foundry resources and Azure AI Search have two keys so one can be regenerated while the other keeps the app running. Switch the app to the secondary key, regenerate the primary, then move the app to the new key.","definition_es":"Los recursos de Foundry y Azure AI Search tienen dos claves para poder regenerar una mientras la otra mantiene la app funcionando. Cambia la app a la clave secundaria, regenera la primaria y luego pasa la app a la clave nueva.","exam_tip_en":"Ordering questions: regenerating the key the app uses first causes downtime. Storing keys in Key Vault does not revoke a leaked key.","exam_tip_es":"En preguntas de orden: regenerar primero la clave que usa la app provoca una interrupción. Guardar las claves en Key Vault no revoca una clave filtrada.","relevance":"media"},{"subskill":"1.3","name_en":"Private endpoints and network isolation","name_es":"Private endpoints y aislamiento de red","definition_en":"Disabling public network access and adding a private endpoint puts the Foundry or Search resource on a private IP in your virtual network. Virtual network rules and service endpoints restrict which subnets can reach the public endpoint.","definition_es":"Deshabilitar el acceso de red público y agregar un private endpoint deja el recurso de Foundry o Search en una IP privada de tu red virtual. Las reglas de red virtual y los service endpoints limitan qué subredes pueden llegar al endpoint público.","exam_tip_en":"No internet exposure means private endpoint. NSGs, Azure Firewall and Application Gateway do not lock down a PaaS endpoint, and IAM controls who manages the resource, not network access.","exam_tip_es":"Sin exposición a internet significa private endpoint. Los NSG, Azure Firewall y Application Gateway no cierran un endpoint PaaS, y IAM controla quién administra el recurso, no el acceso de red.","relevance":"media"},{"subskill":"1.3","name_en":"Quota, TPM and HTTP 429 throttling","name_es":"Cuota, TPM y limitación HTTP 429","definition_en":"Quota is assigned per deployment in tokens per minute (TPM), with a derived requests-per-minute (RPM) limit. Going over it returns HTTP 429, and clients should retry with exponential backoff and jitter, honoring the retry-after header.","definition_es":"La cuota se asigna por implementación en tokens por minuto (TPM), con un límite de solicitudes por minuto (RPM) derivado. Al superarla se recibe HTTP 429, y el cliente debe reintentar con backoff exponencial y jitter, respetando el encabezado retry-after.","exam_tip_en":"Retrying immediately or creating a new thread fails again. To raise capacity, move quota between deployments, request more quota, or use Global or provisioned deployments.","exam_tip_es":"Reintentar de inmediato o crear un thread nuevo vuelve a fallar. Para tener más capacidad, mueve cuota entre implementaciones, pide más cuota o usa implementaciones Global o aprovisionadas.","relevance":"alta"},{"subskill":"1.3","name_en":"Diagnostic settings and Azure Monitor metrics","name_es":"Configuración de diagnóstico y métricas de Azure Monitor","definition_en":"Diagnostic settings send resource logs (for example the RequestResponse category) and metrics to Log Analytics, Storage or Event Hubs. Metrics such as token usage, model availability rate and provisioned utilization show cost, outages and capacity pressure.","definition_es":"La configuración de diagnóstico envía registros del recurso (por ejemplo la categoría RequestResponse) y métricas a Log Analytics, Storage o Event Hubs. Métricas como el uso de tokens, la tasa de disponibilidad del modelo y la utilización aprovisionada muestran costo, caídas y presión de capacidad.","exam_tip_en":"Cost rising with flat traffic: look at token usage. Telling capacity errors from outages: model availability rate and provisioned utilization. Step-by-step debugging of one run needs tracing, not metrics.","exam_tip_es":"Si el costo sube y el tráfico no: revisa el uso de tokens. Para distinguir errores de capacidad de caídas: tasa de disponibilidad del modelo y utilización aprovisionada. Depurar paso a paso una ejecución requiere tracing, no métricas.","relevance":"media"},{"subskill":"1.4","name_en":"Guardrails and content filters","name_es":"Guardrails y filtros de contenido","definition_en":"A guardrail is a named set of controls attached to a model deployment or an agent. Each control pairs a risk (hate, sexual, violence, self-harm, jailbreak, protected material, PII and others) with intervention points (user input, tool call, tool response, output) and an action (block or annotate).","definition_es":"Un guardrail es un conjunto con nombre de controles asociado a una implementación de modelo o a un agente. Cada control une un riesgo (odio, sexual, violencia, autolesión, jailbreak, material protegido, PII y otros) con puntos de intervención (entrada del usuario, llamada a herramienta, respuesta de herramienta, salida) y una acción (bloquear o anotar).","exam_tip_en":"Annotate only flags content, so it is wrong when harm must be prevented. To stop data going to an MCP server, scan the tool call. An agent guardrail overrides the deployment guardrail.","exam_tip_es":"Anotar solo marca el contenido, así que es incorrecto si hay que impedir el daño. Para evitar que los datos lleguen a un servidor MCP, se inspecciona la llamada a herramienta. El guardrail del agente reemplaza al de la implementación.","relevance":"alta"},{"subskill":"1.4","name_en":"Severity threshold (Low, Medium, High)","name_es":"Umbral de severidad (bajo, medio, alto)","definition_en":"Harm categories are scored by severity, and the filter threshold is the lowest severity that gets blocked. A Low threshold blocks low, medium and high content, so it is the strictest; a High threshold blocks only high-severity content.","definition_es":"Las categorías de daño se califican por severidad, y el umbral del filtro es la severidad más baja que se bloquea. Un umbral bajo bloquea contenido bajo, medio y alto, así que es el más estricto; un umbral alto bloquea solo el contenido de severidad alta.","exam_tip_en":"Classic trap: thinking Low is permissive. Lowering the threshold blocks more, so it cannot fix false positives. Protected material is match or no-match and does not change with severity.","exam_tip_es":"Trampa clásica: pensar que bajo es permisivo. Bajar el umbral bloquea más, así que no corrige falsos positivos. El material protegido es coincidencia o no y no cambia con la severidad.","relevance":"alta"},{"subskill":"1.4","name_en":"Prompt Shields","name_es":"Prompt Shields","definition_en":"Prompt Shields detect user prompt attacks (jailbreaks typed by the user) and document attacks, also called indirect prompt injection (instructions hidden in documents, emails, tool output or grounding data). They run as part of guardrails or through the Content Safety API.","definition_es":"Prompt Shields detecta ataques en el prompt del usuario (jailbreaks escritos por el usuario) y ataques en documentos, también llamados inyección indirecta de prompts (instrucciones ocultas en documentos, correos, salidas de herramientas o datos de grounding). Funciona dentro de los guardrails o mediante la API de Content Safety.","exam_tip_en":"Hidden instructions in a file or retrieved content need Prompt Shields for documents; the user-prompt shield only scans what the user types. Harm filters and blocklists do not stop injection.","exam_tip_es":"Las instrucciones ocultas en un archivo o contenido recuperado requieren Prompt Shields para documentos; el escudo del prompt del usuario solo revisa lo que el usuario escribe. Los filtros de daño y las listas de bloqueo no detienen la inyección.","relevance":"alta"},{"subskill":"1.4","name_en":"Protected material detection and custom blocklists","name_es":"Detección de material protegido y listas de bloqueo personalizadas","definition_en":"Protected material detection flags known copyrighted text (lyrics, articles, recipes) and code from public GitHub repositories in model output, with citations for code. Custom blocklists block exact terms or patterns specific to your organization.","definition_es":"La detección de material protegido marca texto con derechos de autor conocido (letras, artículos, recetas) y código de repositorios públicos de GitHub en la salida del modelo, con citas en el caso del código. Las listas de bloqueo personalizadas bloquean términos o patrones exactos propios de la organización.","exam_tip_en":"Copyright or licensed code in output means protected material, not Prompt Shields. Company-specific forbidden words mean a blocklist, not a severity change.","exam_tip_es":"Derechos de autor o código con licencia en la salida es material protegido, no Prompt Shields. Palabras prohibidas propias de la empresa significan lista de bloqueo, no cambio de severidad.","relevance":"media"},{"subskill":"1.4","name_en":"Microsoft responsible AI principles","name_es":"Principios de IA responsable de Microsoft","definition_en":"The six principles are fairness, reliability and safety, privacy and security, inclusiveness, transparency, and accountability. They guide design choices such as disclosing AI use, adding human review and protecting personal data.","definition_es":"Los seis principios son equidad, confiabilidad y seguridad, privacidad y seguridad, inclusión, transparencia y responsabilidad. Orientan decisiones de diseño como avisar del uso de IA, agregar revisión humana y proteger los datos personales.","exam_tip_en":"Telling users the AI processed their data is transparency. Human approval before decisions about pay or credit is accountability. Equal outcomes across groups is fairness.","exam_tip_es":"Avisar a los usuarios que la IA procesó sus datos es transparencia. La aprobación humana antes de decidir sobre pagos o crédito es responsabilidad. Resultados iguales entre grupos es equidad.","relevance":"media"},{"subskill":"2.1","name_en":"AIProjectClient and get_openai_client()","name_es":"AIProjectClient y get_openai_client()","definition_en":"AIProjectClient (package azure-ai-projects) connects to a Foundry project endpoint with an Entra credential. Its get_openai_client() method returns an OpenAI-compatible client authenticated for that project, used to call any deployment by its deployment name.","definition_es":"AIProjectClient (paquete azure-ai-projects) se conecta al endpoint de un proyecto de Foundry con una credencial de Entra. Su método get_openai_client() devuelve un cliente compatible con OpenAI autenticado para ese proyecto, que se usa para llamar a cualquier implementación por su nombre.","exam_tip_en":"The model parameter is the deployment name you chose, not the base model family. A custom name like trail-guide-chat is valid.","exam_tip_es":"El parámetro model es el nombre de la implementación que elegiste, no la familia del modelo base. Un nombre personalizado como trail-guide-chat es válido.","relevance":"alta"},{"subskill":"2.1","name_en":"Responses API","name_es":"Responses API","definition_en":"The Responses API (`responses.create`) is the recommended stateful API for Azure OpenAI and Foundry agents. It takes input and optional instructions, supports built-in tools and server-side conversation state, and returns the text in `output_text`.","definition_es":"Responses API (`responses.create`) es la API con estado recomendada para Azure OpenAI y los agentes de Foundry. Recibe input e instructions opcionales, admite herramientas integradas y estado de conversación en el servidor, y devuelve el texto en `output_text`.","exam_tip_en":"Chat Completions is stateless (you resend messages and read choices[0].message.content). `responses.retrieve` reads an existing response; it does not send a new prompt.","exam_tip_es":"Chat Completions no guarda estado (reenvías los mensajes y lees choices[0].message.content). `responses.retrieve` lee una respuesta existente; no envía un prompt nuevo.","relevance":"alta"},{"subskill":"2.1","name_en":"Retrieval-augmented generation (RAG)","name_es":"Generación aumentada por recuperación (RAG)","definition_en":"RAG retrieves relevant chunks from a knowledge source (usually Azure AI Search), adds them to the prompt and instructs the model to answer only from them, with citations. It grounds answers in private or changing data without retraining the model.","definition_es":"RAG recupera fragmentos relevantes de una fuente de conocimiento (normalmente Azure AI Search), los agrega al prompt e indica al modelo que responda solo con ellos y cite las fuentes. Fundamenta las respuestas en datos privados o cambiantes sin volver a entrenar el modelo.","exam_tip_en":"Fresh or private facts mean RAG; tone, format or style means fine-tuning. If the app already retrieves and answers are still incomplete, the fix is in the prompt or generation, not \"switch to RAG\".","exam_tip_es":"Datos nuevos o privados significan RAG; tono, formato o estilo significan fine-tuning. Si la app ya recupera y las respuestas siguen incompletas, el arreglo está en el prompt o la generación, no en \"pasar a RAG\".","relevance":"alta"},{"subskill":"2.1","name_en":"Structured outputs (JSON schema)","name_es":"Salidas estructuradas (JSON schema)","definition_en":"Structured outputs force the model to return JSON that strictly matches a supplied JSON schema, set through response_format or the text format option with strict mode. JSON mode only guarantees valid JSON, not a specific shape.","definition_es":"Las salidas estructuradas obligan al modelo a devolver JSON que cumple exactamente un JSON schema dado, configurado con response_format o la opción de formato de texto en modo strict. El modo JSON solo garantiza JSON válido, no una forma concreta.","exam_tip_en":"Choose it when downstream code needs guaranteed fields. response_format shapes the output but never forces a tool call.","exam_tip_es":"Elígelo cuando el código posterior necesita campos garantizados. response_format da forma a la salida, pero nunca obliga a llamar una herramienta.","relevance":"media"},{"subskill":"2.1","name_en":"Built-in evaluators (groundedness, relevance, retrieval)","name_es":"Evaluadores integrados (groundedness, relevancia, recuperación)","definition_en":"Foundry evaluations score datasets or live traffic with AI-assisted evaluators (an LLM acts as judge) such as Groundedness, Relevance, Retrieval, Coherence, Fluency and Response Completeness, plus NLP metrics such as F1, BLEU and ROUGE and risk and safety evaluators. They run from the portal or the azure-ai-evaluation SDK.","definition_es":"Las evaluaciones de Foundry califican conjuntos de datos o tráfico real con evaluadores asistidos por IA (un LLM actúa como juez) como Groundedness, Relevance, Retrieval, Coherence, Fluency y Response Completeness, además de métricas NLP como F1, BLEU y ROUGE y evaluadores de riesgo y seguridad. Se ejecutan desde el portal o con el SDK azure-ai-evaluation.","exam_tip_en":"Fabricated claims means Groundedness; answer off-topic means Relevance; wrong chunks retrieved means Retrieval. F1 and ROUGE need a reference answer and do not detect unsupported claims.","exam_tip_es":"Afirmaciones inventadas significa Groundedness; respuesta fuera de tema significa Relevance; fragmentos equivocados significa Retrieval. F1 y ROUGE necesitan una respuesta de referencia y no detectan afirmaciones sin respaldo.","relevance":"alta"},{"subskill":"2.2","name_en":"Foundry Agent Service","name_es":"Foundry Agent Service","definition_en":"Foundry Agent Service hosts agents defined by a model deployment, instructions and tools, and runs them on the Responses API with server-side conversation state, tracing and guardrails. Agents are versioned, and publishing an agent gives it its own agent identity and endpoint.","definition_es":"Foundry Agent Service hospeda agentes definidos por una implementación de modelo, instrucciones y herramientas, y los ejecuta sobre Responses API con estado de conversación en el servidor, tracing y guardrails. Los agentes tienen versiones, y al publicar un agente este recibe su propia identidad de agente y su endpoint.","exam_tip_en":"An isolated identity with its own RBAC and audit trail means a published agent with a distinct agent identity, not the shared project identity.","exam_tip_es":"Una identidad aislada con su propio RBAC y su registro de auditoría significa un agente publicado con identidad propia, no la identidad compartida del proyecto.","relevance":"alta"},{"subskill":"2.2","name_en":"Agent tools","name_es":"Herramientas del agente","definition_en":"Built-in tools include File Search (vector store over uploaded files), Code Interpreter (sandboxed Python), Grounding with Bing Search, Azure AI Search, OpenAPI, MCP, function calling and computer use. Function calling returns the call to your code, which runs it and submits the result.","definition_es":"Las herramientas integradas son File Search (vector store sobre archivos subidos), Code Interpreter (Python en sandbox), Grounding with Bing Search, Azure AI Search, OpenAPI, MCP, function calling y computer use. Con function calling la llamada vuelve a tu código, que la ejecuta y envía el resultado.","exam_tip_en":"Math or CSV charts means Code Interpreter; public current web data means Bing grounding; files uploaded in the chat means File Search; a large private index means Azure AI Search. A remote tool server with optional human approval per call (`require_approval`) means the MCP tool.","exam_tip_es":"Cálculos o gráficos de un CSV significan Code Interpreter; datos web públicos actuales significan Bing grounding; archivos subidos al chat significan File Search; un índice privado grande significa Azure AI Search. Un servidor de herramientas remoto con aprobación humana opcional por llamada (`require_approval`) significa la herramienta MCP.","relevance":"alta"},{"subskill":"2.2","name_en":"tool_choice","name_es":"tool_choice","definition_en":"The `tool_choice` parameter controls whether the model calls tools: \"auto\" (the model decides), \"required\" (must call at least one tool), \"none\" (no tools) or a specific tool type to force that tool. It can be set on the agent or per run or response.","definition_es":"El parámetro `tool_choice` controla si el modelo llama herramientas: \"auto\" (el modelo decide), \"required\" (debe llamar al menos una), \"none\" (ninguna) o un tipo de herramienta específico para forzar esa herramienta. Se puede fijar en el agente o en cada ejecución o respuesta.","exam_tip_en":"If runs skip the knowledge tool, \"auto\" is the cause and \"required\" is the fix. response_format and toolset do not force a call.","exam_tip_es":"Si las ejecuciones se saltan la herramienta de conocimiento, \"auto\" es la causa y \"required\" es la solución. response_format y toolset no obligan a llamar una herramienta.","relevance":"alta"},{"subskill":"2.2","name_en":"Conversations and threads","name_es":"Conversaciones y threads","definition_en":"A conversation is a durable object that stores all items of a dialogue: user and assistant messages, tool calls and tool outputs. Saving its ID and passing it on later requests restores the full history; threads play the same role in the classic Agents API.","definition_es":"Una conversación es un objeto persistente que guarda todos los elementos de un diálogo: mensajes del usuario y del asistente, llamadas y salidas de herramientas. Guardar su ID y enviarlo en solicitudes posteriores recupera todo el historial; los threads cumplen la misma función en la API clásica de Agents.","exam_tip_en":"Continue the same case days later with tool history means store and reuse the conversation ID. Summaries or keeping only the last answer lose tool steps.","exam_tip_es":"Continuar el mismo caso días después con el historial de herramientas significa guardar y reutilizar el ID de la conversación. Los resúmenes o guardar solo la última respuesta pierden los pasos de herramientas.","relevance":"alta"},{"subskill":"2.2","name_en":"Agent memory","name_es":"Memoria del agente","definition_en":"Agent memory (preview) is a managed long-term store that keeps user preferences, chat summaries and procedural knowledge across separate conversations. The agent reads and writes it through the memory search tool, scoped per user.","definition_es":"La memoria del agente (preview) es un almacén administrado de largo plazo que guarda preferencias del usuario, resúmenes de chat y conocimiento de procedimientos entre conversaciones distintas. El agente la lee y escribe con la herramienta de búsqueda de memoria, con un ámbito por usuario.","exam_tip_en":"Personalization across different conversations means memory. A conversation is short-term for one dialogue; knowledge is curated organizational content.","exam_tip_es":"La personalización entre conversaciones distintas significa memoria. Una conversación es de corto plazo para un diálogo; el conocimiento es contenido organizacional curado.","relevance":"media"},{"subskill":"2.2","name_en":"Multi-agent workflows","name_es":"Workflows multiagente","definition_en":"Foundry workflows chain agents and logic nodes (if/else, for each, set variable, ask a question) with shared Power Fx variables, either in a visual builder or YAML. Patterns include sequential, human in the loop and group chat; Microsoft Agent Framework is the code-first equivalent.","definition_es":"Los workflows de Foundry encadenan agentes y nodos lógicos (if/else, for each, asignar variable, hacer una pregunta) con variables Power Fx compartidas, en un editor visual o en YAML. Los patrones son secuencial, humano en el ciclo y chat de grupo; Microsoft Agent Framework es el equivalente basado en código.","exam_tip_en":"Deterministic step-by-step processing means sequential; an approval checkpoint is an Ask a question node. Group chat routes dynamically and is not deterministic.","exam_tip_es":"El procesamiento determinista paso a paso significa secuencial; un punto de aprobación es un nodo Ask a question. El chat de grupo enruta de forma dinámica y no es determinista.","relevance":"media"},{"subskill":"2.3","name_en":"System message and few-shot prompting","name_es":"Mensaje del sistema y prompting few-shot","definition_en":"The system message sets the role, scope, tone and rules of the model. Few-shot prompting adds a few input and output examples to the prompt so the model copies a format or classification style without retraining.","definition_es":"El mensaje del sistema define el rol, el alcance, el tono y las reglas del modelo. El prompting few-shot agrega algunos ejemplos de entrada y salida al prompt para que el modelo copie un formato o un estilo de clasificación sin reentrenar.","exam_tip_en":"Limit answers to one domain means system message instructions. Show what correct output looks like without training means few-shot. Temperature does not change scope.","exam_tip_es":"Limitar las respuestas a un dominio significa instrucciones en el mensaje del sistema. Mostrar cómo es la salida correcta sin entrenar significa few-shot. La temperatura no cambia el alcance.","relevance":"alta"},{"subskill":"2.3","name_en":"Sampling parameters (temperature, top_p, max_tokens)","name_es":"Parámetros de muestreo (temperature, top_p, max_tokens)","definition_en":"temperature and top_p control randomness (tune one, not both); lower values give more repeatable output. max_tokens caps output length, stop sequences end generation, and presence or frequency penalties discourage repetition. Reasoning models use a reasoning effort setting instead of temperature.","definition_es":"temperature y top_p controlan la aleatoriedad (ajusta uno, no ambos); valores más bajos dan salidas más repetibles. max_tokens limita la longitud de la salida, las secuencias de parada terminan la generación y las penalizaciones de presencia o frecuencia reducen la repetición. Los modelos de razonamiento usan un ajuste de esfuerzo de razonamiento en lugar de temperature.","exam_tip_en":"Consistent answers for the same prompt means lower temperature. Truncated answers means raise max_tokens. Raising temperature never improves accuracy or completeness.","exam_tip_es":"Respuestas iguales para el mismo prompt significa bajar temperature. Respuestas cortadas significa subir max_tokens. Subir temperature nunca mejora la exactitud ni la completitud.","relevance":"alta"},{"subskill":"2.3","name_en":"OpenTelemetry tracing","name_es":"Tracing con OpenTelemetry","definition_en":"Foundry tracing follows the OpenTelemetry GenAI semantic conventions and exports spans to the Application Insights resource connected to the project. Each span records the model, latency, token usage (gen_ai.usage.input_tokens and output_tokens) and tool calls, nested under a parent span per run.","definition_es":"El tracing de Foundry sigue las convenciones semánticas GenAI de OpenTelemetry y exporta spans al recurso de Application Insights conectado al proyecto. Cada span registra el modelo, la latencia, el uso de tokens (gen_ai.usage.input_tokens y output_tokens) y las llamadas a herramientas, anidados bajo un span padre por ejecución.","exam_tip_en":"Empty Traces tab means connect Application Insights. Message content is not recorded unless content recording is enabled. OTEL_SERVICE_NAME separates services that share one Application Insights resource.","exam_tip_es":"Una pestaña Traces vacía significa conectar Application Insights. El contenido de los mensajes no se registra salvo que se habilite la grabación de contenido. OTEL_SERVICE_NAME separa servicios que comparten un recurso de Application Insights.","relevance":"alta"},{"subskill":"2.3","name_en":"Fine-tuning (SFT, DPO, RFT)","name_es":"Fine-tuning (SFT, DPO, RFT)","definition_en":"Supervised fine-tuning (SFT) trains on JSONL chat examples to teach format, tone or a narrow task. Direct preference optimization (DPO) learns from preferred and rejected answer pairs, and reinforcement fine-tuning (RFT) uses a grader to improve reasoning models. The tuned model is then deployed like any other.","definition_es":"El fine-tuning supervisado (SFT) entrena con ejemplos de chat en JSONL para enseñar formato, tono o una tarea concreta. La optimización directa de preferencias (DPO) aprende de pares de respuestas preferidas y rechazadas, y el fine-tuning por refuerzo (RFT) usa un calificador para mejorar modelos de razonamiento. Luego el modelo ajustado se implementa como cualquier otro.","exam_tip_en":"Fine-tuning does not add fresh facts; use RAG for that. Try prompt engineering and few-shot first, since they need no training cost.","exam_tip_es":"El fine-tuning no agrega datos nuevos; para eso se usa RAG. Prueba primero la ingeniería de prompts y few-shot, que no tienen costo de entrenamiento.","relevance":"media"},{"subskill":"2.3","name_en":"Evaluation gate in CI/CD (ai-agent-evals)","name_es":"Puerta de evaluación en CI/CD (ai-agent-evals)","definition_en":"The microsoft/ai-agent-evals GitHub Action runs agent evaluations from a workflow, authenticated with Azure Login through OpenID Connect. Its inputs include the project endpoint, the judge deployment name, the data path and the agent IDs, and a failing check can block the pull request merge.","definition_es":"La GitHub Action microsoft/ai-agent-evals ejecuta evaluaciones de agentes desde un workflow, autenticada con Azure Login mediante OpenID Connect. Sus entradas incluyen el endpoint del proyecto, el nombre de la implementación juez, la ruta de datos y los IDs de los agentes, y un check fallido puede bloquear el merge del pull request.","exam_tip_en":"Use OIDC federated credentials, not personal access tokens or stored secrets. To block a merge, fail the check and require it with branch protection.","exam_tip_es":"Usa credenciales federadas OIDC, no personal access tokens ni secretos guardados. Para bloquear un merge, haz fallar el check y exígelo con protección de rama.","relevance":"media"},{"subskill":"3.1","name_en":"gpt-image text-to-image generation","name_es":"Generación de texto a imagen con gpt-image","definition_en":"gpt-image-1 series models (and the older DALL-E 3) create images from a prompt with `images.generate`. You set size, quality (low, medium, high), number of images, output format and background, and gpt-image models return base64 data.","definition_es":"Los modelos de la serie gpt-image-1 (y el anterior DALL-E 3) crean imágenes a partir de un prompt con `images.generate`. Se configuran el tamaño, la calidad (low, medium, high), la cantidad de imágenes, el formato de salida y el fondo, y los modelos gpt-image devuelven datos en base64.","exam_tip_en":"A brand-new image from words only means generate. Image models have no temperature parameter, so \"lower temperature\" answers are distractors.","exam_tip_es":"Una imagen nueva a partir de texto significa generate. Los modelos de imagen no tienen parámetro temperature, así que las respuestas de \"bajar temperature\" son distractores.","relevance":"alta"},{"subskill":"3.1","name_en":"Inpainting with a mask","name_es":"Inpainting con máscara","definition_en":"Inpainting edits only part of an image: `images.edit` receives the image, a prompt and a PNG mask of the same size whose fully transparent pixels mark the area to change. Pixels outside the mask keep their original values.","definition_es":"El inpainting edita solo una parte de una imagen: `images.edit` recibe la imagen, un prompt y una máscara PNG del mismo tamaño cuyos píxeles totalmente transparentes marcan la zona a cambiar. Los píxeles fuera de la máscara conservan sus valores originales.","exam_tip_en":"Remove or replace one object while keeping lighting and style means edit with a mask. Changing the prompt, the seed or using image variations regenerates the whole image.","exam_tip_es":"Quitar o cambiar un objeto conservando la iluminación y el estilo significa editar con máscara. Cambiar el prompt, la semilla o usar variaciones regenera toda la imagen.","relevance":"alta"},{"subskill":"3.1","name_en":"input_fidelity","name_es":"input_fidelity","definition_en":"The `input_fidelity` parameter of gpt-image edits sets how closely the output keeps the style and features of the input images, especially faces and product details. Setting it to high preserves identity; it is not supported by gpt-image-1-mini.","definition_es":"El parámetro `input_fidelity` de las ediciones con gpt-image define cuánto conserva la salida el estilo y los rasgos de las imágenes de entrada, sobre todo rostros y detalles de producto. Con el valor high se conserva la identidad; gpt-image-1-mini no lo admite.","exam_tip_en":"Keep the person or product recognizable means input_fidelity high. Simply including the input image does not guarantee fidelity.","exam_tip_es":"Mantener reconocible a la persona o el producto significa input_fidelity high. Incluir la imagen de entrada no garantiza la fidelidad por sí solo.","relevance":"media"},{"subskill":"3.1","name_en":"Sora video generation and remix","name_es":"Generación de video con Sora y remix","definition_en":"Sora 2 video generation is asynchronous: `videos.create` starts a job, `videos.retrieve` polls its status until completed or failed, and `download_content` downloads the MP4. `input_reference` gives a first frame for image-to-video, and `remix` edits a finished video with one change while keeping its motion.","definition_es":"La generación de video con Sora 2 es asíncrona: `videos.create` inicia un trabajo, `videos.retrieve` consulta su estado hasta completed o failed, y `download_content` descarga el MP4. `input_reference` da un primer cuadro para video a partir de imagen, y `remix` edita un video terminado con un solo cambio conservando su movimiento.","exam_tip_en":"Download only after status is completed. Fix an approved clip with remix, not by regenerating. Real people, faces and copyrighted characters are rejected by policy.","exam_tip_es":"Descarga solo cuando el estado sea completed. Corrige un clip aprobado con remix, no regenerándolo. Las personas reales, los rostros y los personajes con derechos se rechazan por política.","relevance":"media"},{"subskill":"3.2","name_en":"Multimodal chat input (image_url)","name_es":"Entrada multimodal en chat (image_url)","definition_en":"Vision-capable models such as GPT-4o or GPT-4.1 accept images in the user message as an image content part with a URL or a base64 data URL, next to text parts. They generate captions, alt text, and answers about charts, screenshots and photos.","definition_es":"Los modelos con visión, como GPT-4o o GPT-4.1, aceptan imágenes en el mensaje del usuario como una parte de contenido de imagen con una URL o una data URL en base64, junto a partes de texto. Generan descripciones, texto alternativo y respuestas sobre gráficos, capturas y fotos.","exam_tip_en":"Base64 pasted inside the text string or put in metadata is not read as an image. For exact bounding boxes, use Azure Vision or Custom Vision, not a chat model.","exam_tip_es":"Un base64 pegado dentro del texto o en los metadatos no se lee como imagen. Para cuadros delimitadores exactos usa Azure Vision o Custom Vision, no un modelo de chat.","relevance":"alta"},{"subskill":"3.2","name_en":"Azure Vision Image Analysis 4.0","name_es":"Image Analysis 4.0 de Azure Vision","definition_en":"Image Analysis 4.0 returns visual features chosen per call: caption, dense captions, tags, objects with bounding boxes, people, smart crops and read (OCR). Bounding boxes are given as x and y of the top-left corner plus width and height.","definition_es":"Image Analysis 4.0 devuelve las características visuales elegidas en cada llamada: caption, dense captions, tags, objetos con cuadros delimitadores, personas, recortes inteligentes y read (OCR). Los cuadros delimitadores se dan como x e y de la esquina superior izquierda más ancho y alto.","exam_tip_en":"Generic tags or captions with no training means Image Analysis, not Custom Vision. The bottom-right corner must be computed from x+w and y+h.","exam_tip_es":"Etiquetas o descripciones genéricas sin entrenamiento significan Image Analysis, no Custom Vision. La esquina inferior derecha se calcula con x+w e y+h.","relevance":"media"},{"subskill":"3.2","name_en":"OCR with the Read API","name_es":"OCR con la API Read","definition_en":"The Read OCR model extracts printed and handwritten text with lines, words, bounding polygons and confidence. It is available in Azure Vision (synchronous in Image Analysis 4.0) and as prebuilt-read in Document Intelligence for multipage documents.","definition_es":"El modelo OCR Read extrae texto impreso y manuscrito con líneas, palabras, polígonos delimitadores y nivel de confianza. Está disponible en Azure Vision (sincrónico en Image Analysis 4.0) y como prebuilt-read en Document Intelligence para documentos de varias páginas.","exam_tip_en":"Just extract text with minimum effort means Read. Azure Language cannot read pixels. Tables and structure need prebuilt-layout instead.","exam_tip_es":"Solo extraer texto con el menor esfuerzo significa Read. Azure Language no puede leer píxeles. Las tablas y la estructura requieren prebuilt-layout.","relevance":"alta"},{"subskill":"3.2","name_en":"Custom Vision classification and object detection","name_es":"Clasificación y detección de objetos en Custom Vision","definition_en":"Custom Vision trains image classifiers (multiclass or multilabel) or object detectors from your tagged images. The workflow is create project, upload and tag images, train, evaluate precision, recall and mAP, then publish an iteration; compact domains can be exported for offline or mobile use.","definition_es":"Custom Vision entrena clasificadores de imágenes (multiclase o multietiqueta) o detectores de objetos con tus imágenes etiquetadas. El flujo es crear el proyecto, subir y etiquetar imágenes, entrenar, evaluar precisión, recall y mAP, y publicar una iteración; los dominios compact se pueden exportar para uso sin conexión o móvil.","exam_tip_en":"Location or counting needs object detection, not classification. Offline or iOS needs a compact domain. The app sees nothing until the iteration is published.","exam_tip_es":"Ubicar o contar requiere detección de objetos, no clasificación. Sin conexión o iOS requiere un dominio compact. La app no ve nada hasta que la iteración se publica.","relevance":"media"},{"subskill":"3.2","name_en":"Content Understanding standard and pro mode","name_es":"Modo estándar y modo pro de Content Understanding","definition_en":"Azure Content Understanding analyzers turn documents, images, audio and video into structured fields. Standard mode handles one input per call for any modality and returns confidence and grounding; pro mode accepts several documents plus reference data and reasons across them, for documents only.","definition_es":"Los analizadores de Azure Content Understanding convierten documentos, imágenes, audio y video en campos estructurados. El modo estándar procesa una entrada por llamada en cualquier modalidad y devuelve confianza y grounding; el modo pro acepta varios documentos y datos de referencia y razona entre ellos, solo para documentos.","exam_tip_en":"Any image or video scenario means standard mode. Cross-document validation against contracts means pro mode. Both modes use field schemas. Per-segment video descriptions are string fields with method generate.","exam_tip_es":"Cualquier escenario de imagen o video significa modo estándar. Validar entre documentos contra contratos significa modo pro. Ambos modos usan esquemas de campos. Las descripciones por segmento de video son campos string con método generate.","relevance":"media"},{"subskill":"3.3","name_en":"Image moderation with Content Safety","name_es":"Moderación de imágenes con Content Safety","definition_en":"Content Safety analyze image scores pictures for hate, sexual, violence and self-harm by severity. Multimodal analysis can also score an image together with its accompanying text, including text found inside the image.","definition_es":"El análisis de imágenes de Content Safety califica las imágenes por severidad en odio, sexual, violencia y autolesión. El análisis multimodal también puede calificar una imagen junto con su texto, incluido el texto que aparece dentro de la imagen.","exam_tip_en":"Unsafe pixels need image moderation; OCR plus keyword scanning misses visual harm such as violence. Image moderation alone does not stop hidden instructions.","exam_tip_es":"Los píxeles inseguros necesitan moderación de imágenes; OCR más búsqueda de palabras no detecta daño visual como la violencia. La moderación de imágenes sola no detiene instrucciones ocultas.","relevance":"alta"},{"subskill":"3.3","name_en":"Prompt injection through images","name_es":"Inyección de prompts mediante imágenes","definition_en":"Attackers can hide instructions as text inside images or uploaded files that a multimodal model reads. Prompt Shields for documents (indirect attacks) detect them, and Spotlighting marks untrusted content so the model treats it as data rather than instructions.","definition_es":"Los atacantes pueden ocultar instrucciones como texto dentro de imágenes o archivos subidos que un modelo multimodal lee. Prompt Shields para documentos (ataques indirectos) las detecta, y Spotlighting marca el contenido no confiable para que el modelo lo trate como datos y no como instrucciones.","exam_tip_en":"The user-prompt shield does not inspect text extracted from images. When both unsafe images and hidden instructions must be stopped, combine image moderation with Prompt Shields for documents.","exam_tip_es":"El escudo del prompt del usuario no revisa el texto extraído de imágenes. Si hay que detener imágenes inseguras e instrucciones ocultas, combina moderación de imágenes con Prompt Shields para documentos.","relevance":"alta"},{"subskill":"3.3","name_en":"Content credentials (C2PA) for generated media","name_es":"Credenciales de contenido (C2PA) para medios generados","definition_en":"Images and videos generated by Azure OpenAI models carry C2PA content credentials, a signed manifest stating that the content was AI-generated. It supports transparency and provenance checks downstream.","definition_es":"Las imágenes y los videos generados por modelos de Azure OpenAI llevan credenciales de contenido C2PA, un manifiesto firmado que indica que el contenido fue generado por IA. Ayuda a la transparencia y a verificar el origen más adelante.","exam_tip_en":"Prove or disclose that media is AI-generated means content credentials (transparency principle), not a watermark you add in the prompt.","exam_tip_es":"Demostrar o informar que un medio fue generado por IA significa credenciales de contenido (principio de transparencia), no una marca de agua pedida en el prompt.","relevance":"baja"},{"subskill":"3.3","name_en":"Output filters for generated images and video","name_es":"Filtros de salida para imágenes y video generados","definition_en":"Image and video generation deployments apply input and output content filters: prompts that request harmful, real-person or copyrighted content are rejected, and generated outputs are scanned before return. A rejected request returns a content policy error instead of media.","definition_es":"Las implementaciones de generación de imágenes y video aplican filtros de contenido a la entrada y la salida: se rechazan los prompts que piden contenido dañino, personas reales o material con derechos, y las salidas generadas se revisan antes de devolverse. Una solicitud rechazada devuelve un error de política de contenido en lugar del medio.","exam_tip_en":"A failed generation job is often a policy rejection, not a quota problem. Annotate-only settings flag but do not stop unsafe content.","exam_tip_es":"Un trabajo de generación fallido suele ser un rechazo por política, no un problema de cuota. La opción de solo anotar marca, pero no detiene el contenido inseguro.","relevance":"media"},{"subskill":"4.1","name_en":"Named entity recognition and entity linking","name_es":"Reconocimiento de entidades con nombre y vinculación de entidades","definition_en":"NER (`recognize_entities`) returns named items such as people, places, organizations and dates with category, offset and confidence. Entity linking (`recognize_linked_entities`) matches entities to a knowledge base (Wikipedia) and returns a URL, data source and every match location.","definition_es":"NER (`recognize_entities`) devuelve elementos con nombre como personas, lugares, organizaciones y fechas con su categoría, posición y confianza. La vinculación de entidades (`recognize_linked_entities`) relaciona las entidades con una base de conocimiento (Wikipedia) y devuelve una URL, la fuente de datos y la ubicación de cada coincidencia.","exam_tip_en":"Words like tour or visit are key phrases, not entities. Entity linking does not detect language; only detect_language does.","exam_tip_es":"Palabras como recorrido o visita son frases clave, no entidades. La vinculación de entidades no detecta el idioma; solo lo hace detect_language.","relevance":"media"},{"subskill":"4.1","name_en":"PII detection and redaction","name_es":"Detección y redacción de PII","definition_en":"PII entity recognition finds personal data and returns entities plus redactedText. `piiCategories` limits detection to listed categories, and the redaction policy can be characterMask (default, replaces characters), entityMask (replaces with the type, such as [PERSON_1]) or noMask.","definition_es":"El reconocimiento de entidades PII encuentra datos personales y devuelve las entidades y redactedText. `piiCategories` limita la detección a las categorías indicadas, y la política de redacción puede ser characterMask (predeterminada, reemplaza caracteres), entityMask (reemplaza por el tipo, como [PERSON_1]) o noMask.","exam_tip_en":"Categories not listed in piiCategories are neither detected nor redacted. There is no generic Contact category; use Email, PhoneNumber and so on.","exam_tip_es":"Las categorías que no están en piiCategories no se detectan ni se redactan. No existe una categoría genérica Contact; usa Email, PhoneNumber y otras.","relevance":"alta"},{"subskill":"4.1","name_en":"Sentiment analysis and opinion mining","name_es":"Análisis de sentimiento y minería de opiniones","definition_en":"Sentiment analysis labels documents and sentences as positive, negative, neutral or mixed with confidence scores. With opinion mining enabled (`show_opinion_mining`), it also links opinions to aspects, for example \"battery\" with \"short\".","definition_es":"El análisis de sentimiento etiqueta documentos y oraciones como positivos, negativos, neutros o mixtos con puntajes de confianza. Con la minería de opiniones habilitada (`show_opinion_mining`), también relaciona opiniones con aspectos, por ejemplo \"batería\" con \"corta\".","exam_tip_en":"Sentiment about specific product features means opinion mining. Acting on low-confidence sentiment results violates reliability and safety.","exam_tip_es":"El sentimiento sobre características concretas de un producto significa minería de opiniones. Actuar sobre resultados de sentimiento con baja confianza viola la confiabilidad y seguridad.","relevance":"media"},{"subskill":"4.1","name_en":"Azure Translator (text, document and custom)","name_es":"Azure Translator (texto, documentos y personalizado)","definition_en":"Translator translates text synchronously, translates whole documents asynchronously while keeping their format, and supports Custom Translator models trained on your parallel data for domain terminology. Automatic language detection picks one source language per request.","definition_es":"Translator traduce texto de forma sincrónica, traduce documentos completos de forma asíncrona conservando su formato y admite modelos de Custom Translator entrenados con tus datos paralelos para la terminología del dominio. La detección automática elige un idioma de origen por solicitud.","exam_tip_en":"Mixed-language text must be split into single-language segments first. Domain terms translated wrong means Custom Translator. Reading support for dyslexia means Immersive Reader.","exam_tip_es":"El texto con idiomas mezclados debe dividirse antes en segmentos de un solo idioma. Términos del dominio mal traducidos significa Custom Translator. El apoyo de lectura para dislexia significa Immersive Reader.","relevance":"media"},{"subskill":"4.1","name_en":"LLM text analysis with structured output","name_es":"Análisis de texto con LLM y salida estructurada","definition_en":"A language model in Foundry can classify, summarize and extract custom fields from text in one call and return JSON that matches a schema. It is flexible for combined or custom tasks, while Azure Language gives fixed task-specific operations with predictable output.","definition_es":"Un modelo de lenguaje en Foundry puede clasificar, resumir y extraer campos personalizados de un texto en una sola llamada y devolver JSON que cumple un esquema. Es flexible para tareas combinadas o personalizadas, mientras que Azure Language ofrece operaciones fijas por tarea con salida predecible.","exam_tip_en":"Custom fields or several tasks combined into one JSON for an agent points to an LLM with structured outputs. A single standard task with minimum effort points to the Azure Language operation.","exam_tip_es":"Campos personalizados o varias tareas combinadas en un JSON para un agente apuntan a un LLM con salidas estructuradas. Una sola tarea estándar con el menor esfuerzo apunta a la operación de Azure Language.","relevance":"media"},{"subskill":"4.2","name_en":"Real-time speech to text","name_es":"Speech to text en tiempo real","definition_en":"Real-time speech recognition streams audio from a microphone or call and returns interim and final results with low latency, through the Speech SDK. It supports language identification, diarization and phrase lists to boost specific words.","definition_es":"El reconocimiento de voz en tiempo real transmite audio de un micrófono o de una llamada y devuelve resultados parciales y finales con baja latencia mediante el Speech SDK. Admite identificación de idioma, diarización y listas de frases para reforzar palabras concretas.","exam_tip_en":"Live calls or captions mean real-time STT. Batch transcription only works on finished recordings.","exam_tip_es":"Llamadas en vivo o subtítulos significan STT en tiempo real. La transcripción por lotes solo funciona con grabaciones terminadas.","relevance":"alta"},{"subskill":"4.2","name_en":"Batch and fast transcription","name_es":"Transcripción por lotes y rápida","definition_en":"Batch transcription processes large sets of stored audio files asynchronously from Blob Storage URLs, with results returned later. Fast transcription is a synchronous REST API that returns the transcript of one file faster than real time, with diarization and language options.","definition_es":"La transcripción por lotes procesa de forma asíncrona grandes conjuntos de archivos de audio guardados, a partir de URL de Blob Storage, y entrega los resultados después. La transcripción rápida es una API REST sincrónica que devuelve la transcripción de un archivo más rápido que el tiempo real, con diarización y opciones de idioma.","exam_tip_en":"Thousands of archived recordings overnight means batch. One recorded file with a result needed right away means fast transcription.","exam_tip_es":"Miles de grabaciones archivadas durante la noche significan lotes. Un archivo grabado con resultado inmediato significa transcripción rápida.","relevance":"media"},{"subskill":"4.2","name_en":"Text to speech with SSML","name_es":"Text to speech con SSML","definition_en":"Neural text to speech converts text into natural voices. SSML (Speech Synthesis Markup Language) controls the output: phoneme for exact pronunciation, say-as for dates and numbers, prosody for rate, pitch and volume, break for pauses and mstts:express-as for speaking styles.","definition_es":"Text to speech neural convierte texto en voces naturales. SSML (Speech Synthesis Markup Language) controla la salida: phoneme para la pronunciación exacta, say-as para fechas y números, prosody para velocidad, tono y volumen, break para pausas y mstts:express-as para estilos de habla.","exam_tip_en":"Mispronounced technical terms with minimum effort means phoneme (or a custom lexicon), not a custom neural voice. say-as handles formats, not pronunciation.","exam_tip_es":"Términos técnicos mal pronunciados con el menor esfuerzo significa phoneme (o un léxico personalizado), no una voz neuronal personalizada. say-as maneja formatos, no la pronunciación.","relevance":"alta"},{"subskill":"4.2","name_en":"Voice Live API and realtime audio models","name_es":"Voice Live API y modelos de audio en tiempo real","definition_en":"The Voice Live API and gpt-realtime models provide low-latency speech-in, speech-out conversations for voice agents over WebSocket or WebRTC. They handle turn detection, interruptions and noise suppression without chaining separate STT, LLM and TTS calls.","definition_es":"Voice Live API y los modelos gpt-realtime ofrecen conversaciones de voz a voz con baja latencia para agentes de voz mediante WebSocket o WebRTC. Manejan la detección de turnos, las interrupciones y la supresión de ruido sin encadenar llamadas separadas de STT, LLM y TTS.","exam_tip_en":"Microsoft Learn recommends WebRTC for client apps (lowest latency) and WebSocket for server-to-server. Embeddings never decode audio.","exam_tip_es":"Microsoft Learn recomienda WebRTC para apps cliente (menor latencia) y WebSocket para comunicación entre servidores. Los embeddings nunca decodifican audio.","relevance":"media"},{"subskill":"4.2","name_en":"Custom speech","name_es":"Custom speech","definition_en":"Custom speech adapts a base model of one locale with your text, audio with transcripts or pronunciation data, then deploys it to a custom endpoint. API calls reference the custom speech project ID, and apps set the endpoint ID; when the model expires, requests fall back to the latest base model.","definition_es":"Custom speech adapta un modelo base de una configuración regional con tus textos, audios con transcripciones o datos de pronunciación, y luego lo implementa en un endpoint personalizado. Las llamadas de API hacen referencia al ID del proyecto de custom speech, y las apps configuran el ID del endpoint; cuando el modelo expira, las solicitudes pasan al modelo base más reciente.","exam_tip_en":"The project property is the custom speech project ID, not the Foundry project. Expiry causes fallback with lower accuracy, not an error or deletion.","exam_tip_es":"La propiedad project es el ID del proyecto de custom speech, no el proyecto de Foundry. La expiración provoca un cambio al modelo base con menos precisión, no un error ni un borrado.","relevance":"media"},{"subskill":"5.1","name_en":"Indexer, data source and skillset","name_es":"Indexer, origen de datos y skillset","definition_en":"An indexer crawls a data source (Blob Storage, Cosmos DB, SQL and others) on a schedule, cracks documents, runs a skillset of AI enrichments and writes results to the index through field mappings. Change detection reprocesses only new or modified content.","definition_es":"Un indexer recorre un origen de datos (Blob Storage, Cosmos DB, SQL y otros) según una programación, extrae el contenido de los documentos, ejecuta un skillset de enriquecimientos con IA y escribe los resultados en el índice mediante mapeos de campos. La detección de cambios solo vuelve a procesar el contenido nuevo o modificado.","exam_tip_en":"Images for the OCR skill come from normalized_images generated by the indexer. outputFieldMappings write enriched values to the index; they do not run skills.","exam_tip_es":"Las imágenes para el skill de OCR vienen de normalized_images generadas por el indexer. outputFieldMappings escriben los valores enriquecidos en el índice; no ejecutan skills.","relevance":"alta"},{"subskill":"5.1","name_en":"Integrated vectorization","name_es":"Vectorización integrada","definition_en":"Integrated vectorization chunks content with the Text Split skill and creates embeddings with the Azure OpenAI Embedding skill during indexing. A vectorizer on the index embeds the user query at search time with the same model.","definition_es":"La vectorización integrada divide el contenido con el skill Text Split y crea embeddings con el skill Azure OpenAI Embedding durante la indexación. Un vectorizer en el índice convierte la consulta del usuario en vector al buscar, con el mismo modelo.","exam_tip_en":"Vector search over PDFs means Text Split plus Azure OpenAI Embedding. Entity recognition, key phrases or language detection do not create vectors.","exam_tip_es":"La búsqueda vectorial sobre PDF significa Text Split más Azure OpenAI Embedding. El reconocimiento de entidades, las frases clave o la detección de idioma no crean vectores.","relevance":"alta"},{"subskill":"5.1","name_en":"Vector search (HNSW and exhaustive KNN)","name_es":"Búsqueda vectorial (HNSW y KNN exhaustivo)","definition_en":"Vector search finds content by meaning by comparing embeddings with a similarity metric such as cosine. HNSW is the fast approximate algorithm for large indexes, and exhaustive KNN scans every vector for exact results at higher cost.","definition_es":"La búsqueda vectorial encuentra contenido por significado comparando embeddings con una métrica de similitud como el coseno. HNSW es el algoritmo aproximado y rápido para índices grandes, y KNN exhaustivo revisa todos los vectores para obtener resultados exactos con un costo mayor.","exam_tip_en":"Same meaning with different wording means vector search. Vector-only search misses exact product codes or IDs.","exam_tip_es":"El mismo significado con otras palabras significa búsqueda vectorial. La búsqueda solo vectorial no encuentra códigos de producto o IDs exactos.","relevance":"alta"},{"subskill":"5.1","name_en":"Hybrid search with RRF","name_es":"Búsqueda híbrida con RRF","definition_en":"Hybrid search runs a keyword (BM25) query and a vector query in one request and merges the two result lists with Reciprocal Rank Fusion (RRF). It handles both exact terms and paraphrased questions.","definition_es":"La búsqueda híbrida ejecuta una consulta por palabra clave (BM25) y una consulta vectorial en la misma solicitud y combina las dos listas de resultados con Reciprocal Rank Fusion (RRF). Cubre tanto términos exactos como preguntas parafraseadas.","exam_tip_en":"Exact codes plus natural language questions means hybrid. Microsoft recommends hybrid plus semantic ranker as the best relevance for RAG.","exam_tip_es":"Códigos exactos más preguntas en lenguaje natural significa búsqueda híbrida. Microsoft recomienda la híbrida más semantic ranker como la mejor relevancia para RAG.","relevance":"alta"},{"subskill":"5.1","name_en":"Semantic ranker","name_es":"Semantic ranker","definition_en":"Semantic ranker reranks the top results of a keyword or hybrid query with a Microsoft language model and can return semantic captions and answers. It needs a semantic configuration that names the title, content and keyword fields.","definition_es":"Semantic ranker reordena los mejores resultados de una consulta por palabra clave o híbrida con un modelo de lenguaje de Microsoft y puede devolver captions y respuestas semánticas. Necesita una configuración semántica que indique los campos de título, contenido y palabras clave.","exam_tip_en":"Semantic ranking only reorders results that were already retrieved; it does not find documents with different wording on its own.","exam_tip_es":"El ranking semántico solo reordena resultados ya recuperados; por sí solo no encuentra documentos con palabras distintas.","relevance":"alta"},{"subskill":"5.1","name_en":"Agentic retrieval (knowledge bases)","name_es":"Recuperación agéntica (knowledge bases)","definition_en":"Agentic retrieval uses an LLM to plan a complex or multi-turn question into subqueries, runs them in parallel over one or more knowledge sources, reranks the results and returns grounding data with references. Agents consume it through a knowledge base in Azure AI Search.","definition_es":"La recuperación agéntica usa un LLM para dividir una pregunta compleja o de varios turnos en subconsultas, las ejecuta en paralelo sobre una o más fuentes de conocimiento, reordena los resultados y devuelve datos de grounding con referencias. Los agentes la usan mediante una knowledge base en Azure AI Search.","exam_tip_en":"Multi-part questions, conversation context and parallel subqueries mean agentic retrieval. Classic RAG sends a single query.","exam_tip_es":"Preguntas de varias partes, contexto de la conversación y subconsultas en paralelo significan recuperación agéntica. El RAG clásico envía una sola consulta.","relevance":"media"},{"subskill":"5.2","name_en":"Document Intelligence prebuilt models","name_es":"Modelos precompilados de Document Intelligence","definition_en":"Prebuilt models extract text and fields without training: read (OCR), layout (text, tables, selection marks, structure) and document-specific models such as invoice, receipt, ID document, tax forms and contracts. Each field comes with a confidence score and bounding region.","definition_es":"Los modelos precompilados extraen texto y campos sin entrenamiento: read (OCR), layout (texto, tablas, marcas de selección y estructura) y modelos por tipo de documento como factura, recibo, documento de identidad, formularios fiscales y contratos. Cada campo viene con un puntaje de confianza y una región delimitadora.","exam_tip_en":"Keep tables and structure without any model deployment means prebuilt-layout. prebuilt-read has no layout. Standard invoices with known fields mean prebuilt-invoice before any custom model.","exam_tip_es":"Conservar tablas y estructura sin implementar un modelo significa prebuilt-layout. prebuilt-read no tiene layout. Facturas estándar con campos conocidos significan prebuilt-invoice antes que un modelo personalizado.","relevance":"alta"},{"subskill":"5.2","name_en":"Custom template, custom neural and composed models","name_es":"Modelos personalizados template, neural y compuestos","definition_en":"Custom template models learn fixed-layout forms from a few labeled samples. Custom neural models generalize across varied layouts of the same document type. A composed model groups several custom models and routes each document to the right one.","definition_es":"Los modelos personalizados template aprenden formularios de diseño fijo con pocas muestras etiquetadas. Los modelos personalizados neural generalizan entre distintos diseños del mismo tipo de documento. Un modelo compuesto agrupa varios modelos personalizados y envía cada documento al adecuado.","exam_tip_en":"Many vendor layouts of one document type means custom neural. Several form types sent to one endpoint means a composed model.","exam_tip_es":"Muchos diseños de proveedores para un mismo tipo de documento significan custom neural. Varios tipos de formulario enviados a un endpoint significan un modelo compuesto.","relevance":"media"},{"subskill":"5.2","name_en":"Markdown output for RAG","name_es":"Salida en Markdown para RAG","definition_en":"The layout model can return content as Markdown (`output_content_format` set to markdown) so headings, paragraphs and tables keep their structure for chunking. Content Understanding prebuilt-documentSearch also returns RAG-ready Markdown.","definition_es":"El modelo layout puede devolver el contenido en Markdown (`output_content_format` con el valor markdown) para que títulos, párrafos y tablas conserven su estructura al dividir en fragmentos. prebuilt-documentSearch de Content Understanding también devuelve Markdown listo para RAG.","exam_tip_en":"Semantic chunking by section needs layout with Markdown output. Tables in that output are rendered as HTML tables inside the Markdown.","exam_tip_es":"La división en fragmentos por sección necesita layout con salida Markdown. Las tablas de esa salida aparecen como tablas HTML dentro del Markdown.","relevance":"media"},{"subskill":"5.2","name_en":"Content Understanding analyzers and field schema","name_es":"Analizadores y esquema de campos de Content Understanding","definition_en":"A Content Understanding analyzer combines a base or prebuilt analyzer, a field schema and model deployments. Each field uses a method: extract (value as written, documents only), classify (one of fixed categories) or generate (value produced by the model).","definition_es":"Un analizador de Content Understanding combina un analizador base o precompilado, un esquema de campos y las implementaciones de modelos. Cada campo usa un método: extract (valor tal como está escrito, solo documentos), classify (una de varias categorías fijas) o generate (valor producido por el modelo).","exam_tip_en":"Fields that generalize across templates without training data point to a custom Content Understanding analyzer. Azure Language cannot read scanned documents.","exam_tip_es":"Campos que generalizan entre plantillas sin datos de entrenamiento apuntan a un analizador personalizado de Content Understanding. Azure Language no puede leer documentos escaneados.","relevance":"alta"},{"subskill":"5.2","name_en":"Field confidence and grounding (estimateFieldSourceAndConfidence)","name_es":"Confianza y grounding por campo (estimateFieldSourceAndConfidence)","definition_en":"In standard mode, enabling estimateFieldSourceAndConfidence makes the analyzer return a confidence score and the source location of each extracted field. Low-confidence fields can be routed to human review instead of straight-through processing.","definition_es":"En modo estándar, habilitar estimateFieldSourceAndConfidence hace que el analizador devuelva un puntaje de confianza y la ubicación de origen de cada campo extraído. Los campos con baja confianza pueden enviarse a revisión humana en lugar de procesarse automáticamente.","exam_tip_en":"Per-field confidence and source location means this setting. Pro mode does not return confidence or grounding, and search.score is search relevance, not extraction confidence.","exam_tip_es":"Confianza y ubicación de origen por campo significa este ajuste. El modo pro no devuelve confianza ni grounding, y search.score es relevancia de búsqueda, no confianza de extracción.","relevance":"media"}];
  const DOMAINS = {
    1: ["Plan and manage an Azure AI solution", "Planear y administrar una solución de Azure AI"],
    2: ["Implement generative AI and agentic solutions", "Implementar soluciones de IA generativa y agénticas"],
    3: ["Implement computer vision solutions", "Implementar soluciones de visión por computadora"],
    4: ["Implement text analysis solutions", "Implementar soluciones de análisis de texto"],
    5: ["Implement information extraction solutions", "Implementar soluciones de extracción de información"]
  };
  const esc = v => String(v == null ? "" : v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const fmt = v => esc(v).replace(/`([^`]+)`/g, "<code>$1</code>");
  const block = (lang, title, body) =>
    `<section class="fc-language-block" data-lang="${lang}"><span class="fc-language-label">${lang === "en" ? "ENGLISH" : "ESPAÑOL"}</span>${title ? `<strong class="fc-language-title">${esc(title)}</strong>` : ""}<div>${fmt(body)}</div></section>`;
  const prev = window.conceptosAzureAi103 || [];
  const icons = prev.map(c => c.icon);
  const glossary = Object.keys(DOMAINS).map(n => ({
    category: `Domain ${n}: ${DOMAINS[n][0]} / Dominio ${n}: ${DOMAINS[n][1]}`,
    icon: icons[n - 1] || icons[0] || "",
    conceptos: TERMS.filter(t => t.subskill.split(".")[0] === n).map(t => ({
      nombre: `${t.name_en} / ${t.name_es}`,
      tipo: `Subskill ${t.subskill} / Subhabilidad ${t.subskill}`,
      tema: `Domain ${n}: ${DOMAINS[n][0]} / Dominio ${n}: ${DOMAINS[n][1]}`,
      relevancia: t.relevance,
      contribucion: block("en", "Definition", t.definition_en) + block("es", "Definición", t.definition_es),
      datoExamen: block("en", "", t.exam_tip_en) + block("es", "", t.exam_tip_es)
    }))
  }));
  window.conceptosAzureAi103 = glossary;
  if (window.studyResources && window.studyResources["azure-ai-103"]) window.studyResources["azure-ai-103"].terms = glossary;
})();
